KG42.register("rules-94c284a2c7ac065da5f480bd",{"id":"15-multiagent_reverse_auction::v141-c-R009","paper":"15-multiagent_reverse_auction","record":{"rule_id":"v141-c-R009","mechanism_id":"v141-a-M01","name":"Prosumer participation","process_stage":"participation","market_meaning":"Participation by available microgrid generators requires yellow-pages registration, the stated admission requirement for this local market. Scope: Available generators seeking participation in the microgrid's hour-ahead reverse auction. Condition: The generator seeks to participate in bidding processes. The aggregator coordinates DER participation by inviting registered agents to participate in the auction. Scope: Aggregator invitations to DER agents in the microgrid reverse auction. Condition: The agents are registered to the yellow pages. Base-price information supplied by cost-function or state-of-charge agents informs the DER bidding agent's decision whether to participate. Scope: DER bidding-agent decisions about joining the next hour's auction. Condition: The DER is available for the next hour. Algorithm 1 conditions DER bidding participation on the comparison with the utility base-price signal: bidders submit when their base price is lower and otherwise drop without participating. Scope: The initial DER participation test in Algorithm 1 for the microgrid reverse auction. Condition: The DER base price is lower than the utility base price; the alternative branch specifies nonparticipation. A bidder that is no longer interested in the new submission drops out and quits the auction for that particular hour. Scope: Continued DER participation during a rebidding round of the hourly microgrid auction. Condition: Supply exceeds demand, prompting a lower-price bidding request, and the bidder is no longer interested in the new submission.","independence_rationale":"Relations governed by the approved function participation.prosumer under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["admission.local_area","coordination.local_operator","coordination.price_signal","participation.prosumer"],"E":[{"edge_id":"v141-c-R009-E001","source":"coordination.local_operator","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R009-C002"],"evidence_ids":["v141-b-g01-E15"]},{"edge_id":"v141-c-R009-E002","source":"coordination.price_signal","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R009-C003"],"evidence_ids":["v141-b-g01-E08"]},{"edge_id":"v141-c-R009-E003","source":"participation.prosumer","target":"coordination.price_signal","type":"conditional_on","constraint_ids":["v141-c-R009-C004"],"evidence_ids":["v141-b-g01-E12"]},{"edge_id":"v141-c-R009-E004","source":"participation.prosumer","target":"admission.local_area","type":"requires","constraint_ids":["v141-c-R009-C001"],"evidence_ids":["v141-b-g01-E16"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Aggregator invitations to DER agents in the microgrid reverse auction. | Available generators seeking participation in the microgrid's hour-ahead reverse auction. | Continued DER participation during a rebidding round of the hourly microgrid auction. | DER bidding-agent decisions about joining the next hour's auction. | The initial DER participation test in Algorithm 1 for the microgrid reverse auction.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E12","v141-b-g01-E15","v141-b-g01-E16","v141-b-g01-E17"]},"x":[{"variable_id":"x_join_decision","symbol":"j","meaning":"Binary participation/submission decision of the DER bidding agent in the current auction round: 1 denotes submitting a bid (participating), 0 denotes dropping and not participating.","kind":"operational","domain":"{0,1}","unit":null,"indices":[],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E12","v141-b-g01-E17"]}],"theta":[{"parameter_id":"theta_p_base_der","symbol":"p_base_DER","meaning":"Base price of the DER bidding agent used in the participation comparison. The source derives it from cost-function or state-of-charge information; no functional form is asserted in this rule.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/kWh","indices":[],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E10","v141-b-g01-E12"]},{"parameter_id":"theta_p_base_util","symbol":"p_base_util","meaning":"Utility base price for the next hour, announced by the aggregator, used as the comparator in Algorithm 1. The source gives example peak and regular values but no single fixed value for this rule.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/kWh","indices":[],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E12"]}],"phi":[{"constraint_id":"v141-c-R009-C001","kind":"logical","role":"core","statement":"Participation by available microgrid generators requires yellow-pages registration, the stated admission requirement for this local market. Scope: Available generators seeking participation in the microgrid's hour-ahead reverse auction. Condition: The generator seeks to participate in bidding processes.","expression":"forall available generator g in the microgrid: participate(g) => registered_yellow_pages(g)","formalization_origin":"source","template_id":null,"members":["participation.prosumer","admission.local_area"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E16","v141-b-g02-e001"]},{"constraint_id":"v141-c-R009-C002","kind":"procedural","role":"core","statement":"The aggregator coordinates DER participation by inviting registered agents to participate in the auction. Scope: Aggregator invitations to DER agents in the microgrid reverse auction. Condition: The agents are registered to the yellow pages.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E15"]},{"constraint_id":"v141-c-R009-C003","kind":"procedural","role":"core","statement":"Base-price information supplied by cost-function or state-of-charge agents informs the DER bidding agent's decision whether to participate. Scope: DER bidding-agent decisions about joining the next hour's auction. Condition: The DER is available for the next hour.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E08"]},{"constraint_id":"v141-c-R009-C004","kind":"logical","role":"core","statement":"Algorithm 1 conditions DER bidding participation on the comparison with the utility base-price signal: bidders submit when their base price is lower and otherwise drop without participating. Scope: The initial DER participation test in Algorithm 1 for the microgrid reverse auction. Condition: The DER base price is lower than the utility base price; the alternative branch specifies nonparticipation.","expression":"if p_base_DER \u003c p_base_util then j = 1 (submit bid) else j = 0 (drop, not participating)","formalization_origin":"source","template_id":null,"members":["participation.prosumer","coordination.price_signal"],"variable_refs":["x_join_decision"],"parameter_refs":["theta_p_base_der","theta_p_base_util"],"evidence_ids":["v141-b-g01-E12","v141-b-g02-e002"]},{"constraint_id":"v141-c-R009-C005","kind":"procedural","role":"core","statement":"A bidder that is no longer interested in the new submission drops out and quits the auction for that particular hour. Scope: Continued DER participation during a rebidding round of the hourly microgrid auction. Condition: Supply exceeds demand, prompting a lower-price bidding request, and the bidder is no longer interested in the new submission.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E17"]}],"pi":[{"evidence_id":"v141-b-g01-E08","location":{"location_id":"src-1b3df4bc99-p04-c1r3__v141-a-M01-participation","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"providing the services he requires in order to achieve his m goals. If the DER is available for the ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"If the DER is available for the next hour, the bidding agent decides whether to join the auction or not according to base price information received from the cost function or the state-of-charge agents."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-1b3df4bc99-p04-c2r1__v141-a-M01-bidding","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"GAME THEORY 1067 Algorithm 1 Agent Negotiations Begin Initialize: All available generators register ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Algorithm 1 Agent Negotiations\nBegin\nInitialize: All available generators register to yellow page;\nLoop\nAggregator agent: inform utility base price, power demand for next hour;\nAggregator agent: request bids;\nif (DER base price \u003c utility base price) then\nBidder agents: inform submit bids;\nelse\nBidder agent: drop not participating;\nend"},{"evidence_id":"v141-b-g01-E15","location":{"location_id":"src-1b3df4bc99-p04-c2r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"The aggregator manages the communication and the infor- his mation exchange between participants to ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The aggregator manages the communication and the information exchange between participants to minimize the cost of the electricity to be purchased for the lumped load. The aggregator agent is the main entity operating the auction process. Its task is to solicit bids form the agents registered to the yellow pages, and to invite them to participate in the auction. The ultimate goal is to purchase the required amount of power with the lowest cost. DERs submit bids to the DER aggregator, declaring the power available to sell and the price for the next hour. Each DER has a generation capacity, marginal cost, and availability."},{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-1b3df4bc99-p04-c2r4__v141-a-M01-participation","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"terminated. All available generators in the microgrid should 1) register to the yellow pages in orde","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"A reverse auction model has been implemented and realistically operated. Algorithm 1 briefly expresses the simplified pseudo code of the proposed reverse auction model. In Algorithm 1, the process is continuous unless the program is terminated. All available generators in the microgrid should register to the yellow pages in order to participate in bidding processes. The required amount of load is assumed to be correctly estimated for each upcoming hour; therefore the aggregator agent has this information ready to inform all agents registered to the yellow page. The main purpose of the aggregator agent is to purchase the required amount of energy with the least cost. The aggregator agent collects the submitted bids and checks whether the submitted supply matches the demand."},{"evidence_id":"v141-b-g01-E17","location":{"location_id":"src-1b3df4bc99-p04-c2r4__v141-a-M01-bidding","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"terminated. All available generators in the microgrid should 1) register to the yellow pages in orde","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"If the supply is higher than the demand, the aggregator sends a new bidding request to the bidding agents by lowering the price. If bidding agents are still interested in the new submission, they submit the new price; otherwise they drop and quit from the auction for that particular hour. The process continues until only one qualified bidder remains in the auction."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-1b3df4bc99-p04-c1r4__v141-a-M01-pricing","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"ter Fc(P) = ai + biPi + ciP2i . (1) reg i=1 din Renewable resources are assumed to be coupled with s","equation_id":null,"figure_id":null,"table_id":"Table I","image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Renewable resources are assumed to be coupled with storage devices. According to the state-of-charge of the batteries, the mood of the agent changes from being greedy, moderate, and relax. The base price changes according the mood of the agent, which determines the duration of the stay of an agent in the auction. Table I shows the base prices of the inverter bidder agents and their dependence on mood.\nTABLE I\nINVERTER BIDDING AGENT MODES\nState-of-Charge | Agents’ Mood | Lowest Bidding\n0 - 30 % | Relax | 0.15 - 0.13 $/kwh\n30 - 60 % | Moderate | 0.13 - 0.11 $/kwh\n60 - 100 % | Greedy | 0.11 - 0.08 $/kwh"},{"evidence_id":"v141-b-g01-E11","location":{"location_id":"src-1b3df4bc99-p04-c1r4__v141-a-M01-pricing","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"ter Fc(P) = ai + biPi + ciP2i . (1) reg i=1 din Renewable resources are assumed to be coupled with s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The utility cost agent basically broadcasts the utility electricity cost for each hour. During the peak hours, it is assumed that the cost of the electricity is much higher than the regular hours of the day. In this paper, utility peak and regular hour prices are defined as 0.33 and 0.14 $/kWh, respectively."},{"evidence_id":"v141-b-g02-e001","location":{"location_id":"src-1b3df4bc99-p04-c2r4__v141-a-M01-participation","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"terminated. All available generators in the microgrid should 1) register to the yellow pages in orde","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"All available generators in the microgrid should register to the yellow pages in order to participate in bidding processes."},{"evidence_id":"v141-b-g02-e002","location":{"location_id":"src-1b3df4bc99-p04-c2r1__v141-a-M01-bidding","page":4,"printed_page":null,"section":"IV. Proposed Methodology","anchor_text":"GAME THEORY 1067 Algorithm 1 Agent Negotiations Begin Initialize: All available generators register ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Begin\n  Initialize: All available generators register to yellow page;\nLoop\n  Aggregator agent: inform utility base price, power demand for next hour;\n  Aggregator agent: request bids;\n  if (DER base price \u003c utility base price) then\n    Bidder agents: inform submit bids;\n  else\n    Bidder agent: drop not participating;\n  end"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"participation.prosumer","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E16","quote":"All available generators in the microgrid should register to the yellow pages in order to participate in bidding processes."}],[{"evidence_id":"v141-b-g01-E15","quote":"The aggregator agent is the main entity operating the auction process. Its task is to solicit bids form the agents registered to the yellow pages, and to invite them to participate in the auction."}],[{"evidence_id":"v141-b-g01-E08","quote":"If the DER is available for the next hour, the bidding agent decides whether to join the auction or not according to base price information received from the cost function or the state-of-charge agents."}],[{"evidence_id":"v141-b-g01-E12","quote":"if (DER base price \u003c utility base price) then\nBidder agents: inform submit bids;\nelse\nBidder agent: drop not participating;\nend"}],[{"evidence_id":"v141-b-g01-E17","quote":"If the supply is higher than the demand, the aggregator sends a new bidding request to the bidding agents by lowering the price. If bidding agents are still interested in the new submission, they submit the new price; otherwise they drop and quit from the auction for that particular hour."}]],"C2_formalization":{"graph_sha256":"745122e720820103a7e0a1911962305b30ad162ac23038a645ed5a7e7202891f","applicability":"formalized","reason":"C001 and C004 have explicit source-supported logical conditions: yellow-pages registration as a prerequisite for participation, and the strict base-price comparison in Algorithm 1. C002, C003, and C005 are procedural or depend on undefined notions such as being 'interested', so no expression is asserted for them. The declared x/theta capture only the binary submit/drop decision and the two base-price inputs used by the C004 test; no values are inferred. B evidence remains unreviewed.","bindings":[{"object_id":"x_join_decision","node_ids":["participation.prosumer"],"edge_ids":["v141-c-R009-E002","v141-c-R009-E003"],"rationale":"The submit/drop participation decision is the operational state of participation.prosumer; the price-signal link and conditional-on edge capture the source relation between the bidding decision and the received base-price information."},{"object_id":"theta_p_base_der","node_ids":["participation.prosumer","coordination.price_signal"],"edge_ids":["v141-c-R009-E002","v141-c-R009-E003"],"rationale":"The DER base price is the bidder-side price input compared in the participation test; it is associated with participation.prosumer and the price-signal relation represented by E002 and E003."},{"object_id":"theta_p_base_util","node_ids":["coordination.price_signal","participation.prosumer"],"edge_ids":["v141-c-R009-E002","v141-c-R009-E003"],"rationale":"The utility base price is the announced price signal against which the DER base price is compared; it belongs to coordination.price_signal and feeds the participation decision through E002 and E003."},{"object_id":"v141-c-R009-C001","node_ids":["participation.prosumer","admission.local_area"],"edge_ids":["v141-c-R009-E004"],"rationale":"C001 formalizes the registration prerequisite for participation; frozen edge E004 represents participation.prosumer requiring admission.local_area."},{"object_id":"v141-c-R009-C004","node_ids":["participation.prosumer","coordination.price_signal"],"edge_ids":["v141-c-R009-E002","v141-c-R009-E003"],"rationale":"C004 formalizes the Algorithm 1 strict comparison between DER base price and utility base price as the participation test; E003 models participation conditional on the price signal, and E002 links the price signal to participation."}],"revision_requests":[]}},"quarantined_references":[]}});
